Rule.Source:
  import sailpoint.object.*;

  import org.apache.log4j.Logger;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-ActiveDirectory ProvisionPolicy Field Value Calculation Rule");
  log.debug("Alpha-Rule-ActiveDirectory Field Value Calculation Rule - STARTS");


  String firstName = "";
  String lastName = "";
  String fullName = "";
  //Remove all the charectors except a-z and A-Z in First Name and Last Name
  if(null != identity.getLastname())
  {
    lastName = identity.getLastname();
    lastName = lastName.replaceAll("[^a-zA-Z]","");
  }
  log.debug("lastName :"+lastName);
  if(null != identity.getFirstname())
  {
    firstName = identity.getFirstname();
    firstName = firstName.replaceAll("[^a-zA-Z]","");
    fullName = firstName.concat(lastName);
  }
  log.debug("firstName : "+firstName);

  /* 
	*sAMAccountName must be less than 20 chars. ->>check the length of fullName, if the length is more than 19, remove the extraCharCount form the *lastName.
  If lastName is not as long as extraCharCount,remove the extraCharCount from firstName.
	*/ 
  int fullNameLength=fullName.length();
  log.debug("fullNameLength : "+fullNameLength);
  if (fullNameLength > 19 )
  {
    int extraCharCount=fullNameLength-19;
    log.debug("extraCharCount"+extraCharCount);
    int lastNameLength=lastName.length();
    int firstNameLength=firstName.length();
    log.debug("lastNameLength"+lastNameLength);

    if (lastNameLength > extraCharCount )
    {
      lastName=lastName.substring(0,lastNameLength-extraCharCount);
      log.debug("lastname"+lastName);
    }else{
      firstName=firstName.substring(0,firstNameLength-extraCharCount);
      log.debug("firstName"+firstName);						
    }
  } 
  //Logic to calculate sAMAccountName, UPN and mail. Call generateUniqueUPN method , which will return UPN.
  Map upnMap = generateUniqueUPN(firstName,lastName);
  String upn = upnMap.get("userPrincipalName");
  String sAMAccountName = upn.replace("@tcs.sailpointiamcoe.com","");
  String mail = upn;

  log.debug("fieldName"+field.getName());

  if(field.getName().equalsIgnoreCase("sAMAccountName"))
  {
    return sAMAccountName;
  }
  if(field.getName().equalsIgnoreCase("userPrincipalName"))
  {
    return upn;
  }
  if(field.getName().equalsIgnoreCase("mail"))
  {
    return mail;
  }

  //Logic to calculate DN. Set OU path based in employeeType, and referring Alpha-Custom-Joiner OU Mappings Custom Object to set OU based on Department and Location 
  if(field.getName().equalsIgnoreCase("distinguishedName"))
  {

    log.debug("distinguishedName calculation");
    String employeeType = identity.getAttribute("userType");
    String userDept = identity.getAttribute("department");
    String userLocation = identity.getAttribute("city");
    String departmentOU = "";
    String locationOU = "";
    String typeOU = "";
    String baseOU = "";

    //TODO: what if the usertype is not correct ot null. Shall we create a temp OU to place the users???
    if(null!=employeeType)
    {
      if("Employee".equalsIgnoreCase(employeeType))
        typeOU = "Permanent Employees";
      else if("Contractor".equalsIgnoreCase(employeeType))
        typeOU = "Contractors";
    }
    // call custom object to get the Department and Location OU based in Users dept and location
    Custom customObj = context.getObject(Custom.class,"Alpha-Custom-Joiner OU Mappings");

    if(null!=customObj)
    {
      baseOU = customObj.get("baseOU");

      Map deptMap = customObj.get("Department");
      if(null != deptMap)
      {
        if(null != deptMap.get(userDept))
          departmentOU = deptMap.get(userDept);
      }

      Map locationMap = customObj.get("Location");
      if(null != locationMap)
      {
        if(null != locationMap.get(userLocation))
          locationOU = locationMap.get(userLocation);
      }

    }

    String distinguishedName = "CN=" + sAMAccountName + ",OU=" + departmentOU + ",OU=" + locationOU + ",OU=" + typeOU + ",OU=Users,OU=" + baseOU+ ",DC=tcs,DC=sailpointiamcoe,DC=com";

    log.debug("distinguishedName is :"+distinguishedName);

    return distinguishedName;
  }
